105		public InsnArg wrapInstruction(MethodNode mth, InsnNode insn, boolean unbind) {
106			InsnNode parent = parentInsn;
107			if (parent == null) {
108				return null;
109			}
110			if (parent == insn) {
111				LOG.debug("Can't wrap instruction info itself: {}", insn);
112				return null;
113			}
114			int i = getArgIndex(parent, this);
115			if (i == -1) {
116				return null;
117			}
118			if (insn.getType() == InsnType.MOVE && this.isRegister()) {
119				// preserve variable name for move insn (needed in `for-each` loop for iteration variable)
120				String name = ((RegisterArg) this).getName();
121				if (name != null) {
122					InsnArg arg = insn.getArg(0);
123					if (arg.isRegister()) {
124						((RegisterArg) arg).setNameIfUnknown(name);
125					} else if (arg.isInsnWrap()) {
126						InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
127						RegisterArg registerArg = wrapInsn.getResult();
128						if (registerArg != null) {
129							registerArg.setNameIfUnknown(name);
130						}
131					}
132				}
133			}
134			RegisterArg resArg = insn.getResult();
135			InsnArg arg = wrapInsnIntoArg(insn);
136			InsnArg oldArg = parent.getArg(i);
137			if (arg.getType() == ArgType.UNKNOWN) {
138				// restore arg type if wrapped insn missing result
139				arg.setType(oldArg.getType());
140			}
141			parent.setArg(i, arg);
142			InsnRemover.unbindArgUsage(mth, oldArg);
143			if (unbind) {
144				InsnRemover.unbindArgUsage(mth, this);
145			}
146			if (resArg != null && !insn.contains(AFlag.FORCE_ASSIGN_INLINE)) {
147				// result not needed in wrapped insn
148				InsnRemover.unbindResult(mth, insn);
149			}
150			return arg;
151		}
