164		public static InsnArg wrapInsnIntoArg(InsnNode insn) {
165			InsnType type = insn.getType();
166			if (type == InsnType.CONST || type == InsnType.MOVE) {
167				if (insn.contains(AFlag.FORCE_ASSIGN_INLINE)) {
168					RegisterArg resArg = insn.getResult();
169					InsnArg arg = wrap(insn);
170					if (resArg != null) {
171						arg.setType(resArg.getType());
172					}
173					return arg;
174				} else {
175					InsnArg arg = insn.getArg(0);
176					insn.add(AFlag.DONT_GENERATE);
177					return arg;
178				}
179			}
180			return wrapArg(insn);
181		}
