185		 * <p>
186		 * This method don't support MOVE and CONST insns!
187		 */
188		public static InsnArg wrapArg(InsnNode insn) {
189			RegisterArg resArg = insn.getResult();
190			InsnArg arg = wrap(insn);
191			switch (insn.getType()) {
192				case CONST:
193				case MOVE:
194					throw new JadxRuntimeException("Don't wrap MOVE or CONST insns: " + insn);
195	
196				case CONST_STR:
