199						resArg.setType(ArgType.STRING);
200					}
201					break;
202				case CONST_CLASS:
203					arg.setType(ArgType.CLASS);
204					if (resArg != null) {
205						resArg.setType(ArgType.CLASS);
206					}
207					break;
208	
209				default:
210					if (resArg != null) {
211						arg.setType(resArg.getType());
212					}
213					break;
214			}
215			return arg;
216		}
