			// to resolve compiler error: "integer number too large"
			cast = true;
		}
		if (cast) {
			if (bytesLen == 8) {
				return numStr + 'L';
			}
			return getCastStr(bytesLen) + numStr;
		}
		return numStr;
	}

	private static String getCastStr(int bytesLen) {
		switch (bytesLen) {
			case 1:
				return "(byte) ";
			case 2:
				return "(short) ";
			case 4:
				return "(int) ";
			case 8:
				return "(long) ";
