1	package jadx.core.codegen.utils;
2	
3	import java.util.List;
4	import java.util.function.BiConsumer;
5	import java.util.regex.Pattern;
6	
7	import org.jetbrains.annotations.Nullable;
8	
9	import jadx.api.CommentsLevel;
10	import jadx.api.ICodeWriter;
11	import jadx.api.data.CommentStyle;
12	import jadx.api.plugins.input.data.attributes.JadxAttrType;
13	import jadx.api.plugins.input.data.attributes.types.SourceFileAttr;
14	import jadx.core.dex.attributes.AType;
15	import jadx.core.dex.attributes.IAttributeNode;
16	import jadx.core.dex.attributes.nodes.JadxCommentsAttr;
17	import jadx.core.dex.attributes.nodes.JadxError;
18	import jadx.core.dex.attributes.nodes.NotificationAttrNode;
19	import jadx.core.dex.attributes.nodes.RenameReasonAttr;
20	import jadx.core.dex.info.ClassInfo;
21	import jadx.core.dex.instructions.args.CodeVar;
22	import jadx.core.dex.instructions.args.RegisterArg;
23	import jadx.core.dex.instructions.args.SSAVar;
24	import jadx.core.dex.nodes.ClassNode;
25	import jadx.core.dex.nodes.ICodeNode;
26	import jadx.core.utils.Utils;
27	
28	public class CodeGenUtils {
29	
30		public static void addErrorsAndComments(ICodeWriter code, NotificationAttrNode node) {
31			addComments(code, node);
32			addErrors(code, node);
33		}
34	
35		public static void addErrors(ICodeWriter code, NotificationAttrNode node) {
36			if (!node.checkCommentsLevel(CommentsLevel.ERROR)) {
37				return;
38			}
39			List<JadxError> errors = node.getAll(AType.JADX_ERROR);
40			if (!errors.isEmpty()) {
41				errors.stream().distinct().sorted().forEach(err -> {
42					addError(code, err.getError(), err.getCause());
43				});
44			}
45		}
46	
47		public static void addError(ICodeWriter code, String errMsg, Throwable cause) {
48			code.startLine("/*  JADX ERROR: ").add(errMsg);
49			if (cause != null) {
50				code.incIndent();
51				Utils.appendStackTrace(code, cause);
52				code.decIndent();
53			}
54			code.add("*/");
55		}
56	
57		public static void addComments(ICodeWriter code, NotificationAttrNode node) {
58			JadxCommentsAttr commentsAttr = node.get(AType.JADX_COMMENTS);
59			if (commentsAttr != null) {
60				commentsAttr.formatAndFilter(node.getCommentsLevel())
61						.forEach(comment -> code.startLine("/* ").addMultiLine(comment).add(" */"));
62			}
63			addCodeComments(code, node, node);
64		}
65	
66		public static void addCodeComments(ICodeWriter code, NotificationAttrNode parent, @Nullable IAttributeNode node) {
67			if (node == null) {
68				return;
69			}
70			if (parent.checkCommentsLevel(CommentsLevel.USER_ONLY)) {
71				addCodeComments(code, node);
72			}
73		}
74	
75		private static void addCodeComments(ICodeWriter code, @Nullable IAttributeNode node) {
76			if (node == null) {
77				return;
78			}
79			boolean startNewLine = node instanceof ICodeNode; // add on same line for instructions
80			for (CodeComment comment : node.getAll(AType.CODE_COMMENTS)) {
81				addCodeComment(code, comment, startNewLine);
82			}
83		}
84	
85		private static void addCodeComment(ICodeWriter code, CodeComment comment, boolean startNewLine) {
86			if (startNewLine) {
87				code.startLine();
88			} else {
89				code.add(' ');
90			}
91			addCommentWithStyle(code, comment.getStyle(), comment.getComment());
92		}
93	
94		public static void addJadxNodeComment(ICodeWriter code, NotificationAttrNode node,
95				CommentsLevel level, BiConsumer<ICodeWriter, String> commentFunc) {
96			if (node.checkCommentsLevel(level)) {
97				code.startLine();
98				addCommentWithStyle(code, CommentStyle.BLOCK_CONDENSED, (commentCode, newLinePrefix) -> {
99					commentCode.add("JADX ").add(level.name()).add(": ");
100					commentFunc.accept(commentCode, newLinePrefix);
101				});
102			}
103		}
104	
105		public static void addJadxComment(ICodeWriter code, CommentsLevel level, String commentStr) {
106			code.startLine();
107			addCommentWithStyle(code, CommentStyle.BLOCK_CONDENSED, "JADX " + level.name() + ": " + commentStr);
108		}
109	
110		private static void addCommentWithStyle(ICodeWriter code, CommentStyle style, String commentStr) {
111			appendMultiLineString(code, "", style.getStart());
112			appendMultiLineString(code, style.getOnNewLine(), commentStr);
113			appendMultiLineString(code, "", style.getEnd());
114		}
115	
116		/**
117		 * Insert comment with function, use second arg as new line prefix
118		 */
119		private static void addCommentWithStyle(ICodeWriter code, CommentStyle style, BiConsumer<ICodeWriter, String> commentFunc) {
120			appendMultiLineString(code, "", style.getStart());
121			commentFunc.accept(code, style.getOnNewLine());
122			appendMultiLineString(code, "", style.getEnd());
123		}
124	
125		private static final Pattern NEW_LINE_PATTERN = Pattern.compile("\\R");
126	
127		private static void appendMultiLineString(ICodeWriter code, String onNewLine, String str) {
128			String[] lines = NEW_LINE_PATTERN.split(str);
129			int linesCount = lines.length;
130			if (linesCount == 0) {
131				return;
132			}
133			code.add(lines[0]);
134			for (int i = 1; i < linesCount; i++) {
135				code.startLine(onNewLine);
136				code.add(lines[i]);
137			}
138		}
139	
140		public static void addClassRenamedComment(ICodeWriter code, ClassNode cls) {
141			ClassInfo classInfo = cls.getClassInfo();
142			if (classInfo.hasAlias()) {
143				addRenamedComment(code, cls, classInfo.getType().getObject());
144			}
145		}
146	
147		public static void addRenamedComment(ICodeWriter code, NotificationAttrNode node, String origName) {
148			addJadxNodeComment(code, node, CommentsLevel.INFO, (commentCode, newLinePrefix) -> {
149				commentCode.add("renamed from: ").add(origName);
150				RenameReasonAttr renameReasonAttr = node.get(AType.RENAME_REASON);
151				if (renameReasonAttr != null) {
152					commentCode.add(", reason: ").add(renameReasonAttr.getDescription());
153				}
154			});
155		}
156	
157		public static void addSourceFileInfo(ICodeWriter code, ClassNode node) {
158			if (!node.checkCommentsLevel(CommentsLevel.INFO)) {
159				return;
160			}
161			SourceFileAttr sourceFileAttr = node.get(JadxAttrType.SOURCE_FILE);
162			if (sourceFileAttr != null) {
163				String fileName = sourceFileAttr.getFileName();
164				String topClsName = node.getTopParentClass().getClassInfo().getShortName();
165				if (topClsName.contains(fileName)) {
166					// ignore similar name
167					return;
168				}
169				addJadxComment(code, CommentsLevel.INFO, "compiled from: " + fileName);
170			}
171		}
172	
173		public static void addInputFileInfo(ICodeWriter code, ClassNode cls) {
174			if (cls.checkCommentsLevel(CommentsLevel.INFO) && cls.getClsData() != null) {
175				String inputFileName = cls.getClsData().getInputFileName();
176				if (inputFileName != null) {
177					ClassNode declCls = cls.getDeclaringClass();
178					if (declCls != null
179							&& declCls.getClsData() != null
180							&& inputFileName.equals(declCls.getClsData().getInputFileName())) {
181						// don't add same comment for inner classes
182						return;
183					}
184					addJadxComment(code, CommentsLevel.INFO, "loaded from: " + inputFileName);
185				}
186			}
187		}
188	
189		public static CodeVar getCodeVar(RegisterArg arg) {
190			SSAVar svar = arg.getSVar();
191			if (svar != null) {
192				return svar.getCodeVar();
193			}
194			return null;
195		}
196	
197		private CodeGenUtils() {
198		}
199	}
