	List<RegisterArg> useList = sVar.getUseList();
	if (useList.isEmpty()) {
		return false;
	}
	int k = 0;
	for (RegisterArg useArg : useList) {
		InsnNode insn = useArg.getParentInsn();
		if (insn != null && forbidNullArgInline(insn, useArg)) {
			k++;
		}
	}
	return k == useList.size();
